15	)
16	
17	// Request download request
18	type Request struct {
19		RawURL string `json:"rawUrl"`
20		URL    string `json:"url"`
21		Extra  any    `json:"extra"`
22		// Labels is used to mark the download task
23		Labels map[string]string `json:"labels"`
24		// Proxy is special proxy config for request
25		Proxy *RequestProxy `json:"proxy"`
26		// SkipVerifyCert is the flag that skip verify cert
27		SkipVerifyCert bool `json:"skipVerifyCert"`
28	}
29	
30	// SetLabels replaces all labels on the request.
31	//
32	// Deprecated: In onResolve and onDone, assign request labels directly.
33	// In onStart and onError, use task.meta.req.setLabels instead.
34	func (r *Request) SetLabels(labels map[string]string) {
35		r.Labels = labels
36	}
37	
38	// PutLabel sets a label on the request.
39	//
40	// Deprecated: In onResolve and onDone, assign request labels directly.
41	// In onStart and onError, use task.meta.req.putLabel instead.
42	func (r *Request) PutLabel(key, value string) {
43		if r.Labels == nil {
44			r.Labels = make(map[string]string)
45		}
46		r.Labels[key] = value
47	}
48	
49	// DelLabel deletes a label from the request.
50	//
51	// Deprecated: In onResolve and onDone, delete request labels directly.
52	// In onStart and onError, use task.meta.req.delLabel instead.
53	func (r *Request) DelLabel(key string) {
54		delete(r.Labels, key)
55	}
56	
57	func (r *Request) Validate() error {
58		if r.URL == "" {
59			return fmt.Errorf("invalid request url")
60		}
