216		DownloadDir                string                 `json:"downloadDir"`    // DownloadDir is the default directory to save the downloaded files
217		MaxRunning                 int                    `json:"maxRunning"`     // MaxRunning is the max running download count
218		ProtocolConfig             map[string]any         `json:"protocolConfig"` // ProtocolConfig is special config for each protocol
219		GithubMirror               *GithubMirrorConfig    `json:"githubMirror"`
220		Extra                      map[string]any         `json:"extra"`
